window.GLOSSARY = [{"term": "Adjective", "def": "A word that describes a noun, like happy, blue, or tall."}, {"term": "Adverb", "def": "A word that adds detail to a verb, adjective, or another adverb, like quickly or very."}, {"term": "Article", "def": "a, an, and the - words that introduce nouns."}, {"term": "Auxiliary verb", "def": "A helping verb such as be, have, do, or a modal."}, {"term": "Clause", "def": "A group of words with a subject and a verb."}, {"term": "Collocation", "def": "Words that often appear together, like make a decision."}, {"term": "Conditional", "def": "An if-structure that links a condition with a result."}, {"term": "Conjunction", "def": "A word that links words or clauses, like and, but, or because."}, {"term": "Determiner", "def": "A word before a noun such as the, some, my, or this."}, {"term": "Gerund", "def": "An -ing form used like a noun, as in Swimming is fun."}, {"term": "Infinitive", "def": "to + base verb (to go), or the base verb alone."}, {"term": "Modal", "def": "Verbs like can, could, may, must, should, will, and would."}, {"term": "Noun", "def": "A word for a person, place, thing, or idea."}, {"term": "Object", "def": "The person or thing that receives the action of the verb."}, {"term": "Participle", "def": "The -ing form or the past form used in perfect and passive structures."}, {"term": "Passive", "def": "A structure that focuses on the action or the receiver (was written)."}, {"term": "Preposition", "def": "A word like in, on, at, by, or for that shows a relationship."}, {"term": "Pronoun", "def": "A word that replaces a noun, like he, she, it, or they."}, {"term": "Subject", "def": "Who or what does the action in a sentence."}, {"term": "Tense", "def": "The form of the verb that shows time."}, {"term": "Transitive verb", "def": "A verb that takes an object, like read a book."}, {"term": "Intransitive verb", "def": "A verb that does not take an object, like sleep or arrive."}];

