window.HARD_QUIZZES = [{"q": "Hardly ___ we arrived when the meeting started.", "options": ["had", "have", "did", "were"], "answer": 0, "topic": "Inversion"}, {"q": "I'd rather you ___ me the truth yesterday.", "options": ["tell", "told", "had told", "have told"], "answer": 2, "topic": "Prefer / rather"}, {"q": "No sooner ___ the door than the phone rang.", "options": ["I opened", "had I opened", "I had opened", "did I open"], "answer": 1, "topic": "Inversion"}, {"q": "She is believed ___ the company last year.", "options": ["to leave", "to have left", "leaving", "left"], "answer": 1, "topic": "Complex passive"}, {"q": "Were I in your position, I ___ accept the offer.", "options": ["will", "would", "would have", "can"], "answer": 1, "topic": "Formal conditional"}, {"q": "The report needs ___ before Friday.", "options": ["finish", "to finish", "finishing", "finished"], "answer": 2, "topic": "Need + -ing"}, {"q": "Not until midnight ___ the results.", "options": ["we received", "did we receive", "we did receive", "had we receive"], "answer": 1, "topic": "Inversion"}, {"q": "He denied ___ the documents.", "options": ["to steal", "stealing", "steal", "stolen"], "answer": 1, "topic": "Verb patterns"}, {"q": "It is essential that every student ___ on time.", "options": ["arrives", "arrive", "arrived", "arriving"], "answer": 1, "topic": "Subjunctive"}, {"q": "Scarcely ___ the film begun when the power failed.", "options": ["has", "had", "did", "was"], "answer": 1, "topic": "Inversion"}, {"q": "She spoke as if she ___ the answer all along.", "options": ["knows", "knew", "had known", "has known"], "answer": 2, "topic": "as if"}, {"q": "The more difficult the task, ___ the reward.", "options": ["greater", "the greater", "greatest", "the greatest"], "answer": 1, "topic": "the...the"}, {"q": "Only by practising every day ___ improve.", "options": ["you can", "can you", "you will", "will you can"], "answer": 1, "topic": "Inversion"}, {"q": "I wish I ___ more attention in class last year.", "options": ["pay", "paid", "had paid", "have paid"], "answer": 2, "topic": "Wish"}, {"q": "He is said ___ a fortune in property.", "options": ["to make", "to have made", "making", "made"], "answer": 1, "topic": "Reporting structures"}, {"q": "Little ___ that the decision would change everything.", "options": ["she knew", "did she know", "she did know", "knew she"], "answer": 1, "topic": "Inversion"}, {"q": "I'd sooner ___ at home than go out in this weather.", "options": ["stay", "to stay", "staying", "stayed"], "answer": 0, "topic": "Prefer structures"}, {"q": "The proposal was objected ___ by several members.", "options": ["to", "for", "with", "at"], "answer": 0, "topic": "Prepositional passive"}, {"q": "Had it not been for your help, we ___ failed.", "options": ["will have", "would have", "had", "would"], "answer": 1, "topic": "Third conditional formal"}, {"q": "She avoided ___ any promises she couldn't keep.", "options": ["to make", "making", "make", "made"], "answer": 1, "topic": "Gerunds"}, {"q": "Whatever ___ happen, we must stay calm.", "options": ["may", "might", "should", "would"], "answer": 0, "topic": "Modals"}, {"q": "The book is worth ___.", "options": ["to read", "reading", "read", "to reading"], "answer": 1, "topic": "Worth + -ing"}, {"q": "On no account ___ this information to anyone.", "options": ["you should give", "should you give", "you give", "give you"], "answer": 1, "topic": "Inversion"}, {"q": "He pretended not ___ me.", "options": ["see", "to see", "seeing", "saw"], "answer": 1, "topic": "Infinitives"}, {"q": "Such was her surprise that she ___ speak.", "options": ["couldn't", "can't", "won't", "mustn't"], "answer": 0, "topic": "Emphatic such"}, {"q": "It's high time the government ___ action.", "options": ["takes", "take", "took", "has taken"], "answer": 2, "topic": "It's time"}, {"q": "The manager insisted that the report ___ rewritten.", "options": ["is", "be", "was", "being"], "answer": 1, "topic": "Subjunctive"}, {"q": "Barely ___ finished dinner when guests arrived.", "options": ["we had", "had we", "we have", "have we"], "answer": 1, "topic": "Inversion"}, {"q": "She is used to ___ criticised for her ideas.", "options": ["be", "being", "been", "to be"], "answer": 1, "topic": "be used to"}, {"q": "Not only ___ late, but he also forgot the files.", "options": ["he was", "was he", "he is", "is he"], "answer": 1, "topic": "Inversion"}, {"q": "I would rather you ___ smoking in the house.", "options": ["don't", "didn't", "not", "won't"], "answer": 1, "topic": "would rather"}, {"q": "The problem appears ___ solved already.", "options": ["to be", "to have been", "being", "have been"], "answer": 1, "topic": "Perfect infinitive"}, {"q": "Under no circumstances ___ leave the building.", "options": ["you should", "should you", "you can", "can you to"], "answer": 1, "topic": "Inversion"}, {"q": "He admitted ___ the password without permission.", "options": ["to use", "using", "use", "used"], "answer": 1, "topic": "Verb + gerund"}, {"q": "So rare ___ the species that scientists were excited.", "options": ["is", "was", "were", "are"], "answer": 1, "topic": "Inversion so/such"}, {"q": "If only I ___ the warning signs earlier.", "options": ["see", "saw", "had seen", "have seen"], "answer": 2, "topic": "If only"}, {"q": "The contract is subject ___ approval by the board.", "options": ["of", "to", "for", "with"], "answer": 1, "topic": "Fixed phrases"}, {"q": "She has difficulty ___ long reports.", "options": ["to write", "writing", "write", "in write"], "answer": 1, "topic": "have difficulty"}, {"q": "Nowhere ___ a more beautiful sunset.", "options": ["I have seen", "have I seen", "I saw", "did I saw"], "answer": 1, "topic": "Inversion"}, {"q": "They are thought ___ the city overnight.", "options": ["to leave", "to have left", "leaving", "left"], "answer": 1, "topic": "Passive reporting"}, {"q": "Much as I ___ to help, I can't stay late tonight.", "options": ["want", "wanted", "would want", "have wanted"], "answer": 0, "topic": "Concessive clauses"}, {"q": "The package was too heavy for her ___ alone.", "options": ["carrying", "to carry", "carry", "carried"], "answer": 1, "topic": "too...to"}, {"q": "I can't help ___ that something is wrong.", "options": ["to feel", "feeling", "feel", "felt"], "answer": 1, "topic": "can't help"}, {"q": "Should you need anything, ___ free to call.", "options": ["you feel", "feel", "feeling", "to feel"], "answer": 1, "topic": "Formal conditionals"}, {"q": "The results left little ___ doubt.", "options": ["for", "to", "of", "in"], "answer": 0, "topic": "Fixed phrases"}, {"q": "He spoke so quietly that we could ___ hear him.", "options": ["hard", "hardly", "harder", "hardest"], "answer": 1, "topic": "hardly"}, {"q": "There is no point ___ further.", "options": ["to argue", "arguing", "argue", "in argue"], "answer": 1, "topic": "no point + -ing"}, {"q": "Seldom ___ such dedication from a trainee.", "options": ["we see", "do we see", "we do see", "see we"], "answer": 1, "topic": "Inversion"}, {"q": "She went on ___ after everyone else had stopped.", "options": ["to talk", "talking", "talk", "talked"], "answer": 1, "topic": "go on + -ing"}, {"q": "Be that ___ it may, we still need a decision.", "options": ["as", "like", "what", "how"], "answer": 0, "topic": "Fixed expressions"}];

window.EXTRA_LESSONS = [{"id": "cleft-sentences", "category": "advanced", "title": "Cleft sentences (It was... that)", "level": "C1", "description": "Emphasise part of a sentence with it-clefts and what-clefts.", "content": {"intro": "Cleft sentences help you highlight one piece of information. They are common in careful speech and writing.", "sections": [{"title": "It-clefts", "text": "It + be + highlighted information + that/who + the rest of the clause.", "examples": [{"correct": "It was Maria who sent the email.", "note": "focus on Maria"}, {"correct": "It was yesterday that we met.", "note": "focus on time"}, {"correct": "It is the cost that worries me most.", "note": ""}]}, {"title": "What-clefts (pseudo-clefts)", "text": "What-clause + be + highlighted information.", "examples": [{"correct": "What I need is a quiet place to work.", "note": ""}, {"correct": "What surprised us was the final score.", "note": ""}, {"correct": "What you should do is call support.", "note": ""}]}, {"title": "All / The only thing", "text": "Similar emphasis with all or the only thing.", "examples": [{"correct": "All I want is a fair chance.", "note": ""}, {"correct": "The only thing that matters is honesty.", "note": ""}]}], "tips": ["Use clefts when you want to correct or strongly focus one detail.", "In speech, stress falls on the highlighted part."]}, "quiz": [{"q": "___ was the noise that woke me up.", "options": ["What", "It", "That", "There"], "answer": 1}, {"q": "What I really need ___ more time.", "options": ["are", "is", "be", "were"], "answer": 1}, {"q": "It was in London ___ they first met.", "options": ["where", "that", "which", "when"], "answer": 1}, {"q": "All she asked for ___ a simple answer.", "options": ["were", "was", "is", "be"], "answer": 1}]}, {"id": "discourse-markers", "category": "advanced", "title": "Discourse markers", "level": "B2", "description": "Words and phrases that organise ideas: however, therefore, on the other hand...", "content": {"intro": "Discourse markers guide the reader or listener through your ideas - contrast, result, addition, and example.", "sections": [{"title": "Contrast", "text": "however, on the other hand, nevertheless, although, whereas, while", "examples": [{"correct": "The plan is costly. However, it may save money later.", "note": ""}, {"correct": "Whereas Sam prefers tea, I drink coffee.", "note": ""}]}, {"title": "Result and reason", "text": "therefore, as a result, consequently, so, because, since", "examples": [{"correct": "Demand rose. As a result, prices increased.", "note": ""}, {"correct": "Since you're here early, we can start.", "note": ""}]}, {"title": "Adding and ordering", "text": "moreover, in addition, furthermore, first, finally, for example", "examples": [{"correct": "The course is practical. Moreover, it is affordable.", "note": ""}, {"correct": "For example, you can practise with short quizzes.", "note": ""}]}, {"title": "Attitude and softening", "text": "frankly, to be honest, apparently, arguably, in my view", "examples": [{"correct": "Frankly, I was disappointed.", "note": ""}, {"correct": "Apparently, the meeting was cancelled.", "note": ""}]}], "tips": ["In formal writing, avoid starting every sentence with And or But - use however or in addition instead.", "Match the marker to the relationship you mean (contrast vs result)."]}, "quiz": [{"q": "The product is popular; ___, it has some flaws.", "options": ["therefore", "however", "moreover", "so"], "answer": 1}, {"q": "Costs went up. ___, we delayed the launch.", "options": ["However", "As a result", "Whereas", "For example"], "answer": 1}, {"q": "The app is free. ___, it works offline.", "options": ["However", "Moreover", "Although", "Whereas"], "answer": 1}, {"q": "___ the delay, everyone stayed calm.", "options": ["Despite", "Although", "However", "Therefore"], "answer": 0}]}, {"id": "noun-phrases", "category": "sentence", "title": "Complex noun phrases", "level": "B2", "description": "Build longer noun groups with modifiers and relative clauses.", "content": {"intro": "Academic and formal English often packs information into noun phrases instead of many short sentences.", "sections": [{"title": "Premodifiers", "text": "Adjectives and nouns before the head noun.", "examples": [{"correct": "a major policy decision", "note": ""}, {"correct": "the national health service", "note": ""}, {"correct": "an unexpected technical problem", "note": ""}]}, {"title": "Postmodifiers", "text": "Prepositional phrases, relative clauses, and participles after the noun.", "examples": [{"correct": "students in the final year", "note": ""}, {"correct": "the report published last week", "note": ""}, {"correct": "people who work night shifts", "note": ""}]}, {"title": "Nominalisation", "text": "Turning verbs or adjectives into nouns for a more formal style.", "examples": [{"correct": "They decided → their decision", "note": ""}, {"correct": "The city developed rapidly → the rapid development of the city", "note": ""}]}], "tips": ["Do not make noun phrases so long that the sentence becomes hard to read.", "In speech, shorter clauses often sound more natural."]}, "quiz": [{"q": "Choose the most natural formal phrase:", "options": ["They improved the system quickly", "the rapid improvement of the system", "improving system rapid", "system the improved"], "answer": 1}, {"q": "The documents ___ on the desk belong to HR.", "options": ["lying", "lie", "to lie", "lied"], "answer": 0}, {"q": "She joined a team ___ renewable energy.", "options": ["works on", "working on", "worked on", "to working on"], "answer": 1}]}, {"id": "hedging", "category": "advanced", "title": "Hedging and cautious language", "level": "C1", "description": "Sound careful and academic: may, tend to, it seems, arguably...", "content": {"intro": "Hedging softens claims so you do not sound more certain than the evidence allows. It is common in academic and professional English.", "sections": [{"title": "Modal hedges", "text": "may, might, could, would appear to, seem to", "examples": [{"correct": "This may explain the delay.", "note": ""}, {"correct": "The results appear to support the theory.", "note": ""}]}, {"title": "Introductory phrases", "text": "It seems that, It is likely that, There is evidence that, Arguably", "examples": [{"correct": "It is likely that demand will rise.", "note": ""}, {"correct": "Arguably, the policy helped small businesses.", "note": ""}]}, {"title": "Approximators", "text": "about, roughly, approximately, a number of, often, generally, typically", "examples": [{"correct": "Roughly 30% of users completed the course.", "note": ""}, {"correct": "Students generally prefer short practice sessions.", "note": ""}]}], "tips": ["Over-hedging can make writing weak. Be clear when evidence is strong.", "In everyday conversation, heavy hedging can sound unnatural."]}, "quiz": [{"q": "Which sentence is more carefully hedged?", "options": ["This proves the theory.", "This may support the theory.", "This always supports the theory.", "This must prove the theory."], "answer": 1}, {"q": "___ 40% of respondents agreed.", "options": ["Exactly every", "Roughly", "Never", "Must"], "answer": 1}, {"q": "The findings ___ to indicate a small improvement.", "options": ["appear", "are", "must", "prove"], "answer": 0}]}];
window.LESSON_EXPANSIONS = {"articles": {"extraSections": [{"title": "Sound, not spelling", "text": "English articles follow sound, not the first letter on the page. Words that begin with a consonant sound take a: a university, a European tour, a one-way street. Words that begin with a vowel sound take an: an hour, an honour, an MBA, an SOS. When you are unsure, say the word out loud and listen for the first sound.", "examples": [{"correct": "a unique opportunity", "note": "starts with /j/"}, {"correct": "an unexpected result", "note": "starts with /ʌ/"}, {"correct": "a historic moment", "note": "many speakers use a before historic"}]}, {"title": "Generic reference", "text": "When you talk about a whole class of things, English offers several patterns. Plural with no article is the most natural in everyday speech: Dogs need exercise. The + singular is more formal or scientific: The dog is a loyal animal. A/an + singular introduces one typical member: A dog needs regular walks.", "examples": [{"correct": "Smartphones have changed communication.", "note": "general, plural"}, {"correct": "The smartphone has changed communication.", "note": "the class as a type"}, {"correct": "A smartphone can store thousands of photos.", "note": "any typical phone"}]}, {"title": "Fixed phrases worth memorising", "text": "Some article patterns are fixed. Learn them as chunks rather than analysing each word: in the morning, at night, go to school, go to hospital (British English for patients), play the piano, the rich and the poor, by car, on foot, in bed when sleeping.", "examples": [{"correct": "She goes to school by bus.", "note": "as a student"}, {"correct": "He is still in hospital after the operation.", "note": "BrE patient"}, {"correct": "They arrived on foot.", "note": "no article"}]}], "extraTips": ["If both speaker and listener know which thing is meant, the is usually safe.", "Names of most countries take no article (France), but the Netherlands, the United States, and the United Kingdom do."]}, "present-simple": {"extraSections": [{"title": "Habits, facts, and schedules", "text": "Present simple covers repeated actions, general truths, and fixed timetables. Adverbs of frequency (always, usually, often, sometimes, rarely, never) normally sit before the main verb but after be: She usually arrives early. She is usually early. With questions and negatives, use do/does: Does he work late? He does not work late.", "examples": [{"correct": "Water boils at 100 degrees Celsius.", "note": "fact"}, {"correct": "The train leaves at 6:40.", "note": "timetable"}, {"correct": "I never drink coffee after 8 p.m.", "note": "habit"}]}, {"title": "State verbs", "text": "Some verbs describe states more than actions: know, believe, own, seem, like, prefer, understand, belong. They rarely appear in continuous forms when they keep that meaning: I know the answer (not I am knowing). A few verbs can be both: I think you are right (opinion) vs I am thinking about the problem (mental activity now).", "examples": [{"correct": "She owns two apartments.", "note": "state"}, {"correct": "I prefer tea to coffee.", "note": "preference"}, {"correct": "This bag belongs to my sister.", "note": "possession"}]}], "extraTips": ["Third-person singular needs -s/-es: watches, studies, goes, has.", "Use present simple for permanent situations; present continuous for temporary ones."]}, "present-perfect": {"extraSections": [{"title": "Experience, result, and unfinished time", "text": "Present perfect links past events to the present. Common uses include life experience (Have you ever tried sushi?), present result (I have lost my keys - so I cannot open the door), and unfinished time periods (I have written three emails today). Specific finished times (yesterday, last year, in 2019) usually need past simple instead.", "examples": [{"correct": "She has visited Rome twice.", "note": "experience"}, {"correct": "Someone has broken the window.", "note": "result now"}, {"correct": "Have you seen the news this morning?", "note": "the morning is still open"}]}, {"title": "for, since, just, already, yet", "text": "for measures duration (for three years). since marks the starting point (since 2020). just means a short time ago. already means sooner than expected. yet appears in questions and negatives near the end of the clause.", "examples": [{"correct": "We have lived here for a decade.", "note": ""}, {"correct": "They have already finished.", "note": ""}, {"correct": "Has the package arrived yet?", "note": ""}]}, {"title": "British and American preferences", "text": "British English often prefers present perfect with just/already/yet. American English sometimes uses past simple in the same situations: I just ate (AmE) vs I have just eaten (BrE). Both are widely understood; choose one style and stay consistent in formal writing.", "examples": [{"correct": "I have just spoken to her. (BrE preferred)", "note": ""}, {"correct": "I just spoke to her. (common in AmE)", "note": ""}]}], "extraTips": ["Do not combine present perfect with a finished past time marker in the same clause.", "been to means went and returned; gone to means went and is still there."]}, "conditionals": {"extraSections": [{"title": "Zero and first", "text": "Zero conditional expresses general truths: If you heat ice, it melts. First conditional talks about real future possibilities: If it rains, we will cancel the picnic. Unless means if not: Unless you hurry, you will miss the bus.", "examples": [{"correct": "If people do not sleep enough, they feel tired.", "note": "zero"}, {"correct": "If she passes the exam, she will celebrate.", "note": "first"}]}, {"title": "Second and third", "text": "Second conditional imagines present or future situations that are unlikely or hypothetical: If I had more free time, I would learn the piano. Third conditional looks back at unreal past situations: If I had left earlier, I would have caught the train. Mixed conditionals combine times when needed.", "examples": [{"correct": "If I were you, I would accept the offer.", "note": "advice"}, {"correct": "If they had checked the map, they would not have got lost.", "note": "third"}]}, {"title": "Formal and inverted forms", "text": "In formal English, if can drop out of some conditionals: Had I known, I would have called. Were she available, she would join us. Should you need help, contact support. These forms are common in careful writing and speeches.", "examples": [{"correct": "Had it not been for your advice, we would have failed.", "note": ""}, {"correct": "Should the situation change, we will write again.", "note": ""}]}], "extraTips": ["In second conditional, were is traditional with all persons after if (If I were...), though was is common in informal speech.", "Comma after the if-clause when it comes first."]}, "passive": {"extraSections": [{"title": "When the passive helps", "text": "Use the passive when the action or the receiver matters more than the doer, when the doer is unknown, or when you want a more formal tone. Academic and news writing use passives often: The results were published last week. The thief was arrested.", "examples": [{"correct": "A new policy has been introduced.", "note": "focus on policy"}, {"correct": "The documents are being reviewed.", "note": "in progress"}]}, {"title": "Form across tenses", "text": "Passive = be in the right tense + past participle. Present: is cleaned. Past: was cleaned. Present perfect: has been cleaned. Future: will be cleaned. Continuous: is being cleaned. Modal: must be cleaned.", "examples": [{"correct": "The report will be finished by Friday.", "note": ""}, {"correct": "The road is being repaired.", "note": ""}]}, {"title": "By-phrases and agent omission", "text": "Add by + agent only when the doer is important or surprising. Otherwise leave the agent out: The window was broken (by someone) is usually enough without naming the person if unknown.", "examples": [{"correct": "The novel was written by a young author.", "note": "agent matters"}, {"correct": "My bike was stolen last night.", "note": "agent unknown"}]}], "extraTips": ["Do not overuse the passive in storytelling; active verbs keep narratives clearer.", "Get-passive (got promoted) is informal and common in spoken English."]}};
window.DEFAULT_LESSON_EXPANSION = {"extraSections": [{"title": "Putting it into practice", "text": "Strong grammar comes from noticing patterns in real English and then producing them yourself. After you read each rule, write two or three original sentences of your own. Compare them with the examples, then check a short quiz while the idea is still fresh. Review weak topics after a day or two so the forms move into long-term memory.", "examples": [{"correct": "Write your own examples - not only copy the ones above.", "note": ""}, {"correct": "Say the sentences aloud to fix the rhythm in your mind.", "note": ""}]}, {"title": "Common learner pitfalls", "text": "Many mistakes come from translating word-for-word from another language. English word order, article use, and verb tense choices often differ from other systems. When a sentence feels odd, try a simpler structure first, then build complexity. Keep a short list of your personal error patterns and revisit it weekly.", "examples": [{"correct": "Prefer clear short sentences while you learn a new form.", "note": ""}, {"correct": "Check tense time markers: yesterday vs since Monday.", "note": ""}]}], "extraTips": ["Spaced practice beats long single sessions for grammar retention.", "Read a short authentic text and underline the structure you just studied."]};
